1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
40	    @Mapping(target = "locality", expression = "java(locality(owner))")
41	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
44	    @Mapping(target = "identityKey",
45	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
46	    @Mapping(target = "telephoneDisplay",
47	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
48	    public abstract OwnerDto toOwnerDto(Owner owner);
49	
50	    /**
51	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
52	     * present (non-null and non-blank), otherwise {@code PHONE}.
53	     */
54	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
55	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
56	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
57	    }
58	
59	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
60	    private static final int ADULT_AGE = 18;
61	
62	    /** The age (in years) at which an owner becomes a senior. */
63	    private static final int SENIOR_AGE = 65;
64	
65	    /**
66	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
67	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
68	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
69	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
70	     * either the birth date or the registration date is absent, so an owner created
71	     * without a birth date has no age band.
72	     */
73	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
74	        LocalDate birthDate = owner.getBirthDate();
75	        LocalDate registrationDate = owner.getRegistrationDate();
76	        if (birthDate == null || registrationDate == null) {
77	            return null;
78	        }
79	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
80	        if (age < ADULT_AGE) {
81	            return OwnerDto.AgeBandEnum.MINOR;
82	        }
83	        if (age < SENIOR_AGE) {
84	            return OwnerDto.AgeBandEnum.ADULT;
85	        }
86	        return OwnerDto.AgeBandEnum.SENIOR;
87	    }
88	
89	    /**
90	     * Derives the owner's {@code locality} (canonical region string) from the
91	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
92	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
93	     * fall back to deriving the region directly from postcode, then city, then
94	     * {@code "UNKNOWN"}.
95	     */
96	    protected String locality(Owner owner) {
97	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
98	                .regionOf(owner.getCustomerCode());
99	        if (region != null) {
100	            return region;
101	        }
102	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
103	    }
104	
105	    /** The top membership level, reachable only with tenure. */
106	    private static final int MAX_MEMBERSHIP_LEVEL = 4;
107	
108	    /**
109	     * The highest level reachable from the pre-tenure factors alone; the top level
110	     * ({@value #MAX_MEMBERSHIP_LEVEL}) is unlocked only by tenure.
111	     */
112	    private static final int PRE_TENURE_MAX_LEVEL = MAX_MEMBERSHIP_LEVEL - 1;
113	
114	    /**
115	     * Tenure, in days since {@code registrationDate}, that must be exceeded to reach the
116	     * top membership level.
117	     */
118	    private static final int TENURE_DAYS_FOR_TOP_LEVEL = 365;
119	
120	    /**
121	     * Returns the owner's membership level, a number from 1 to
122	     * {@value #MAX_MEMBERSHIP_LEVEL}: it starts at 1, gains 1 when an email address is
123	     * present, gains 1 when the owner has no namesakes (namesakeCount is 0), and these
124	     * pre-tenure factors are capped at {@value #PRE_TENURE_MAX_LEVEL}. Level
125	     * {@value #MAX_MEMBERSHIP_LEVEL} is reserved for tenure: it is reached only when the
126	     * owner has more than {@value #TENURE_DAYS_FOR_TOP_LEVEL} days of tenure. A newly
127	     * created owner registers as of the current day and so has zero tenure, meaning a new
128	     * owner never exceeds level {@value #PRE_TENURE_MAX_LEVEL}.
129	     */
130	    public static int membershipLevel(Owner owner) {
131	        int level = 1;
132	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
133	        if (hasEmail) {
134	            level++;
135	        }
136	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
137	        if (noNamesakes) {
138	            level++;
139	        }
140	        // Level 4 is reserved for tenure: cap the pre-tenure factors, then let more than
141	        // TENURE_DAYS_FOR_TOP_LEVEL days of tenure unlock the top level.
142	        level = Math.min(level, PRE_TENURE_MAX_LEVEL);
143	        if (hasTopLevelTenure(owner)) {
144	            level++;
145	        }
146	        return level;
147	    }
148	
149	    /**
150	     * True when the owner's tenure (days between {@code registrationDate} and today)
151	     * exceeds {@value #TENURE_DAYS_FOR_TOP_LEVEL}. An owner with no registration date
152	     * (e.g. legacy seed owners) has no tenure.
153	     */
154	    private static boolean hasTopLevelTenure(Owner owner) {
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        if (registrationDate == null) {
157	            return false;
158	        }
159	        long tenureDays = java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
160	        return tenureDays > TENURE_DAYS_FOR_TOP_LEVEL;
161	    }
162	
163	    /**
164	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
165	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
166	     * customer code or the registration date is absent (e.g. legacy seed owners).
167	     */
168	    protected String membershipNumber(Owner owner) {
169	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
170	            return null;
171	        }
172	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
173	    }
174	
175	    /**
176	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
177	     * been created for this owner's {@code registrationDate}, using the same per-day
178	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
179	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
180	     */
181	    protected boolean bulkSignupWarning(Owner owner) {
182	        LocalDate registrationDate = owner.getRegistrationDate();
183	        if (registrationDate == null) {
184	            return false;
185	        }
186	        long count = ownerRepository.findAll().stream()
187	                .filter(existing -> !existing.getId().equals(owner.getId()))
188	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
189	                .count();
190	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
191	    }
192	
193	    /**
194	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
195	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
196	     * legacy seed owners).
197	     */
198	    protected Integer checkDigit(Owner owner) {
199	        String customerCode = owner.getCustomerCode();
200	        if (customerCode == null) {
201	            return null;
202	        }
203	        int sum = 0;
204	        boolean dbl = true;
205	        for (int i = customerCode.length() - 1; i >= 0; i--) {
206	            char c = customerCode.charAt(i);
207	            if (c < '0' || c > '9') {
208	                continue;
209	            }
210	            int d = c - '0';
211	            if (dbl) {
212	                d *= 2;
213	                if (d > 9) {
214	                    d -= 9;
215	                }
216	            }
217	            sum += d;
218	            dbl = !dbl;
219	        }
220	        return (10 - (sum % 10)) % 10;
221	    }
222	
223	    public abstract Owner toOwner(OwnerDto ownerDto);
224	
225	    @Mapping(target = "id", ignore = true)
226	    @Mapping(target = "pets", ignore = true)
227	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
228	
229	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
230	
231	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
232	
233	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
234	        OwnerPageDto ownerPageDto = new OwnerPageDto();
235	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
236	        ownerPageDto.setPage(ownerPage.getNumber());
237	        ownerPageDto.setSize(ownerPage.getSize());
238	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
239	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
240	        return ownerPageDto;
241	    }
242	}
