8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Builds and interprets the owner {@code customerCode}, the single region-and-hash identity every
12	 * derived value (membership number, its check digit, the create audit line and the {@code locality})
13	 * now hangs off.
14	 *
15	 * <p>The code is {@code <REGION>-<HASH8>} where REGION is the {@link #region(Owner) region} derived
16	 * from the owner's postcode (falling back to the city, then {@code "UNKNOWN"}) and HASH8 is the first
17	 * eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}. Sequence
18	 * numbers are no longer part of the identity, so the code depends only on the owner's own fields.
19	 */
20	public final class CustomerCodes {
21	
22	    /** Fixed city-to-region table (mirrors the read-only {@code locality} mapping). */
23	    private static final Map<String, String> CITY_REGION = Map.of(
24	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    private CustomerCodes() {
33	    }
34	
35	    /** Builds the {@code <REGION>-<HASH8>} customer code for the owner. */
36	    public static String build(Owner owner) {
37	        return region(owner) + "-" + hash8(owner.getTelephone(), owner.getLastName());
38	    }
39	
